BEGIN;
SET LOCAL search_path=extensions,public,pg_temp;
SELECT no_plan();
INSERT INTO auth.users(id,email,raw_app_meta_data) VALUES('16900000-0000-4000-8000-000000000001','guard169@example.test','{"_invite_provisioned":true}');
CREATE TEMP TABLE bg_tenant AS SELECT (public.provision_company_atomic('16900000-0000-4000-8000-000000000001','{"name":"Guard169","slug":"guard169","domain":"guard169.example.test"}')->>'id')::uuid id;
UPDATE public.users SET must_change_password=false WHERE auth_user_id='16900000-0000-4000-8000-000000000001';
INSERT INTO public.platform_admins(user_id,email) VALUES('16900000-0000-4000-8000-000000000001','guard169@example.test');
INSERT INTO public.platform_invoices(id,tenant_id,invoice_number,amount,status) SELECT '16900000-0000-4000-8000-000000000101',id,'PLT-GUARD169',115,'pending' FROM bg_tenant;
INSERT INTO public.platform_invoices(id,tenant_id,invoice_number,amount,status) SELECT '16900000-0000-4000-8000-000000000102',id,'PLT-VOID169',115,'void' FROM bg_tenant;
CREATE TEMP TABLE bg_values(label text PRIMARY KEY,value jsonb);
GRANT SELECT ON bg_tenant TO authenticated,service_role;
GRANT ALL ON bg_values TO authenticated,service_role;
SELECT ok(NOT has_function_privilege('service_role','public.claim_my_platform_checkout(uuid)','EXECUTE'),'service cannot impersonate a payer');
SELECT ok(NOT has_function_privilege('authenticated','public.confirm_platform_checkout(uuid,text,text,integer)','EXECUTE'),'payer cannot invent provider mapping');
SELECT ok(NOT has_function_privilege('authenticated','public.claim_notification_digest(uuid,date)','EXECUTE'),'caller cannot claim management delivery');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"16900000-0000-4000-8000-000000000001","aal":"aal2"}',true);
INSERT INTO bg_values VALUES('first',public.claim_my_platform_checkout('16900000-0000-4000-8000-000000000101'));
INSERT INTO bg_values VALUES('retry',public.claim_my_platform_checkout('16900000-0000-4000-8000-000000000101'));
SELECT is((SELECT value->'attempt'->>'id' FROM bg_values WHERE label='first'),(SELECT value->'attempt'->>'id' FROM bg_values WHERE label='retry'),'parallel/retried checkout uses the same reserved attempt');
SELECT is((SELECT value->>'is_new' FROM bg_values WHERE label='retry'),'false','unknown creation is not reissued');
SELECT throws_like($$SELECT public.claim_my_platform_checkout('16900000-0000-4000-8000-000000000102')$$,'PAY003:%','void invoice has no checkout');
SELECT throws_like($$SELECT public.mark_platform_invoice_paid('16900000-0000-4000-8000-000000000102')$$,'PAY003:%','void invoice cannot activate billing');
RESET ROLE;
SELECT is((SELECT count(*)::integer FROM public.platform_payment_attempts WHERE tenant_id=(SELECT id FROM bg_tenant)),1,'only one attempt was created');
SELECT is((SELECT status FROM public.platform_invoices WHERE id='16900000-0000-4000-8000-000000000102'),'void','rejected manual settlement preserves void state');
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT throws_like($$SELECT public.confirm_platform_checkout((SELECT(value->'attempt'->>'id')::uuid FROM bg_values WHERE label='first'),'provider169','https://checkout.moyasar.com/synthetic',1)$$,'PAY002:%','provider amount mismatch rolls back mapping');
SELECT lives_ok($$SELECT public.confirm_platform_checkout((SELECT(value->'attempt'->>'id')::uuid FROM bg_values WHERE label='first'),'provider169','https://checkout.moyasar.com/synthetic',11500)$$,'exact mapping can be confirmed');
SELECT throws_like($$SELECT public.confirm_platform_checkout((SELECT(value->'attempt'->>'id')::uuid FROM bg_values WHERE label='first'),'other169','https://checkout.moyasar.com/other',11500)$$,'PAY002:%','mapping cannot be rebound to another checkout');
INSERT INTO bg_values VALUES('digest',public.claim_notification_digest((SELECT id FROM bg_tenant),(now() AT TIME ZONE 'Asia/Riyadh')::date));
SELECT is(public.claim_notification_digest((SELECT id FROM bg_tenant),(now() AT TIME ZONE 'Asia/Riyadh')::date),NULL::jsonb,'a competing digest cannot take a live lease');
SELECT lives_ok($$SELECT public.prepare_notification_digest((SELECT(value->>'id')::uuid FROM bg_values WHERE label='digest'),(SELECT(value->>'claim_token')::uuid FROM bg_values WHERE label='digest'),'{}')$$,'delivery payload is retained before provider call');
SELECT throws_like($$SELECT public.prepare_notification_digest((SELECT(value->>'id')::uuid FROM bg_values WHERE label='digest'),(SELECT(value->>'claim_token')::uuid FROM bg_values WHERE label='digest'),'{}'::jsonb||'{"changed":true}')$$,'DIGEST_PAYLOAD_CHANGED','retry cannot silently replace retained content');
SELECT is(public.finish_notification_digest((SELECT(value->>'id')::uuid FROM bg_values WHERE label='digest'),(SELECT(value->>'claim_token')::uuid FROM bg_values WHERE label='digest'),'{"status":"failed"}'),true,'failed provider delivery is recorded');
INSERT INTO bg_values VALUES('digest-retry',public.claim_notification_digest((SELECT id FROM bg_tenant),(now() AT TIME ZONE 'Asia/Riyadh')::date));
SELECT is((SELECT value->>'id' FROM bg_values WHERE label='digest'),(SELECT value->>'id' FROM bg_values WHERE label='digest-retry'),'failed same-day delivery can be retried');
SELECT isnt((SELECT value->>'claim_token' FROM bg_values WHERE label='digest'),(SELECT value->>'claim_token' FROM bg_values WHERE label='digest-retry'),'retry gets a new fencing token');
SELECT is((SELECT value->'payload' FROM bg_values WHERE label='digest-retry'),'{}'::jsonb,'retry retains the original delivery payload');
SELECT throws_like($$SELECT public.finish_notification_digest((SELECT(value->>'id')::uuid FROM bg_values WHERE label='digest'),(SELECT(value->>'claim_token')::uuid FROM bg_values WHERE label='digest'),'{"status":"sent"}')$$,'DIGEST_CLAIM_STALE','an old worker cannot finish a newer claim');
SELECT is(public.finish_notification_digest((SELECT(value->>'id')::uuid FROM bg_values WHERE label='digest-retry'),(SELECT(value->>'claim_token')::uuid FROM bg_values WHERE label='digest-retry'),'{"status":"sent"}'),true,'current worker finishes confirmed delivery');
SELECT is(public.claim_notification_digest((SELECT id FROM bg_tenant),(now() AT TIME ZONE 'Asia/Riyadh')::date),NULL::jsonb,'confirmed delivery is never sent twice');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
